mapper.update:
UPDATE agent
SET online_status = #{newStatus},
    offline_reason = #{reason},
    offline_time = #{now},
    update_time = #{now}
WHERE id = #{agentId}
  AND last_seen_time < #{cutoff}
  AND (online_status IS DISTINCT FROM 'SLEEPING')
  AND (online_status IS DISTINCT FROM 'OFFLINE')
  AND deleted = 0
